namespace {
unsigned checks=0,failures=0;
void check(bool value,const char *label){++checks;if(!value){++failures;std::fprintf(stderr,"FAIL FM: %s\n",label);}}
void word(std::vector<uint8_t>& data,size_t at,uint16_t value){data[at]=uint8_t(value>>8);data[at+1]=uint8_t(value);}
void longword(std::vector<uint8_t>& data,size_t at,uint32_t value){word(data,at,uint16_t(value>>16));word(data,at+2,uint16_t(value));}
}
int runAudioFmTests(){using namespace Snatcher;checks=failures=0;std::string error;
 {std::vector<uint8_t> logical(2051,0x42),physical(4096,0x91);std::copy(logical.begin(),logical.end(),physical.begin());
  check(fmAllocationCompatible(logical,physical,error),"actual whole-sector allocation preserves logical prefix and nonzero real tail");
  auto foreign=physical;foreign[2050]^=1;check(!fmAllocationCompatible(logical,foreign,error),"foreign logical prefix rejects before owner mutation");
  foreign=physical;foreign.pop_back();check(!fmAllocationCompatible(logical,foreign,error),"short physical final sector rejected");foreign=physical;foreign.resize(6144);check(!fmAllocationCompatible(logical,foreign,error),"extra sector beyond file-owned allocation rejected");
  check(!fmAllocationCompatible(logical,logical,error),"explicit allocation cannot be silently padded from logical bytes");std::vector<uint8_t> aligned(2048,0x77);check(fmAllocationCompatible(aligned,aligned,error),"sector-aligned logical and physical domains coincide");std::vector<uint8_t> empty;check(!fmAllocationCompatible(empty,empty,error),"empty source has no allocation owner");}

 std::vector<uint8_t> fm(0x3000,0),main(0x6600,0);for(unsigned i=0;i<256;++i){longword(fm,i*4,1024+26*i);size_t at=1024+26*i;fm[at]=uint8_t(i&63);for(unsigned j=1;j<25;++j)fm[at+j]=uint8_t(j+i);}
 std::vector<FmInstrument> instruments;check(parseFmInstruments(fm.data(),fm.size(),instruments,error)&&instruments.size()==256,"all256 bounded synthesis instrument records");check(instruments[63].algorithm==7&&instruments[63].feedback==7&&instruments[0].operators[0].multiple==1&&instruments[0].operators[0].totalLevel==2&&instruments[0].operators[0].releaseRate==6,"instrument normalized algorithm/operator parameters");
 auto prior=instruments;fm[1024+25]=1;check(!parseFmInstruments(fm.data(),fm.size(),instruments,error)&&instruments.size()==prior.size(),"unknown instrument alignment byte rejects transactionally");fm[1024+25]=0;longword(fm,0,1025);check(!parseFmInstruments(fm.data(),fm.size(),instruments,error),"unsupported instrument stride rejects");longword(fm,0,1024);check(!parseFmInstruments(fm.data(),7679,instruments,error),"truncated instrument bank");
 longword(fm,0x1e00,4);longword(fm,0x1e04,4);fm[0x1e08]=255;size_t record=0x6142+8;main[record+2]=9;main[record+3]=3;FmCommandAsset asset;check(readFmCommandAsset(main.data(),main.size(),fm.data(),fm.size(),1,asset,error)&&!asset.music&&asset.channelCount==1&&asset.firstChannel==9&&asset.channels[0]==4&&asset.sourceOffset==0x1e04,"source indexed FM effect resource route");
 longword(fm,0x2846,4);longword(fm,0x284a,4);fm[0x284e]=255;record=0x6142+63*8;main[record]=1;main[record+3]=128;word(main,0x5586,40);check(readFmCommandAsset(main.data(),main.size(),fm.data(),fm.size(),0x013f,asset,error)&&asset.music&&asset.command==63&&asset.bytes.size()==40&&asset.sequenceIndex==0,"source music command low-byte routing and length owner");
 check(!readFmCommandAsset(main.data(),main.size(),fm.data(),fm.size(),0,asset,error)&&!readFmCommandAsset(main.data(),main.size(),fm.data(),fm.size(),255,asset,error),"no-request/fade not misread as asset indices");
 longword(fm,0x284a,40);check(!readFmCommandAsset(main.data(),main.size(),fm.data(),fm.size(),63,asset,error),"FM channel outside source extent rejects");longword(fm,0x284a,4);
 FmSequenceReader reader;FmSequenceEvent event;std::vector<uint8_t> seq={0xea,126,0xee,112,0xe2,151,0xe6,19,4,127,90,0x94,0xd5,0xe7,2,0,0,255};check(reader.start(seq,0,error),"semantic sequence starts from owned bytes");check(reader.next(event,error)&&event.kind==kFmTempo&&event.value==126,"source tempo event");check(reader.next(event,error)&&event.kind==kFmVolume&&event.value==112,"source volume event");check(reader.next(event,error)&&event.kind==kFmInstrument&&event.value==151,"source instrument event");check(reader.next(event,error)&&event.kind==kFmLoop,"source loop marker");check(reader.next(event,error)&&event.kind==kFmNote&&event.note==19&&event.duration==4&&event.gate==127&&event.level==90&&!event.reusedDuration,"explicit note duration/gate/level");check(reader.next(event,error)&&event.note==20&&event.duration==4&&event.gate==127&&event.level==85&&event.reusedDuration&&event.reusedGate,"high-bit note reuses duration/gate with source level operand");check(reader.next(event,error)&&event.kind==kFmLoop&&reader.cursor()==7,"source repeat count2 loops once");reader.next(event,error);reader.next(event,error);check(reader.next(event,error)&&event.kind==kFmLoop&&reader.cursor()==17,"source repeat equality advances after second pass");check(reader.next(event,error)&&event.kind==kFmSequenceEnd&&reader.ended()&&!reader.next(event,error),"terminal event without playback-completion invention");
 seq={0xfe,0,0,0,6,255,0,0xe0,3,255};check(reader.start(seq,0,error)&&reader.next(event,error)&&event.kind==kFmCall&&reader.cursor()==7,"relative call uses operand origin");check(reader.next(event,error)&&event.kind==kFmRest&&event.duration==3,"rest source timing operand");check(reader.next(event,error)&&event.kind==kFmReturn&&reader.cursor()==5&&reader.next(event,error)&&reader.ended(),"one-level source return then terminal");
 seq={0xfd,255,255,255,255};check(reader.start(seq,0,error)&&reader.next(event,error)&&reader.cursor()==0&&!reader.ended(),"negative relative loop remains live without timeout");
 seq={0xe3,2,255};check(reader.start(seq,0,error)&&reader.next(event,error)&&event.kind==kFmPan&&event.value==2&&reader.cursor()==2,"source static stereo control operand");seq={1,2};check(reader.start(seq,0,error)&&!reader.next(event,error)&&reader.cursor()==0,"truncated note transaction rejects");seq={0xe6,1,2,0,4,0xe7,2,1,0};check(reader.start(seq,0,error)&&reader.next(event,error)&&reader.next(event,error)&&reader.next(event,error)&&reader.cursor()==1&&reader.loopVolume()==1,"source loop volume mutation accumulates on repeat");seq={0xf8,0xfa,255};check(reader.start(seq,0,error)&&reader.next(event,error)&&event.kind==kFmIgnoredByte&&reader.next(event,error)&&event.kind==kFmIgnoredByte,"only original RTS control families are explicit ignored events");

 const uint8_t controls[]={0xe1,0xe3,0xe4,0xe5,0xeb,0xed,0xef,0xf0,0xf1,0xf2,0xf3,0xf4,0xf5,0xf9,0xfb,0xfc};const unsigned lengths[]={2,1,3,3,2,1,2,1,3,1,0,2,2,1,1,2};
 for(unsigned i=0;i<sizeof(controls);++i){seq.assign(1,controls[i]);for(unsigned j=0;j<lengths[i];++j)seq.push_back(1);seq.push_back(255);check(reader.start(seq,0,error)&&reader.next(event,error)&&reader.cursor()==1+lengths[i],"complete bounded source control operand family");if(lengths[i]){seq.resize(lengths[i]);check(reader.start(seq,0,error)&&!reader.next(event,error)&&reader.cursor()==0,"truncated new control remains transactional");}}
 seq={1,2,127,10,0xf3,1,2,3,0xfc,2,255,255};check(reader.start(seq,0,error)&&reader.next(event,error)&&event.kind==kFmNote&&event.hasSlide&&event.slideDelay==1&&event.slideTicks==2&&event.slideNote==3&&event.slideIncrement==-254&&reader.cursor()==11,"source note-attached slide consumes little-endian FC increment");seq.resize(10);check(reader.start(seq,0,error)&&!reader.next(event,error)&&reader.cursor()==0,"truncated attached slide cannot publish partial note");
 seq={0xea,126,0xee,80,0x6c,12,6,107,255};check(reader.start(seq,0,error,true)&&reader.next(event,error)&&reader.next(event,error)&&reader.next(event,error)&&event.kind==kFmPercussion&&event.note==12&&event.duration==12&&event.gate==6&&event.level==107,"source percussion tracks use their distinct four-byte note grammar");
 seq={0xe8,1,2,127,10,0xe9,2,255,1,255};check(reader.start(seq,0,error)&&reader.next(event,error)&&reader.next(event,error)&&reader.next(event,error)&&reader.loopVolume()==-1&&reader.loopPitch()==8&&reader.cursor()==1,"second loop volume/pitch accumulators are signed source words");
 std::printf("FM assets/semantic events: %u checks, %u failures\n",checks,failures);return failures?1:0;
}
#ifdef SNATCHER_AUDIO_FM_TEST_MAIN
static bool readFile(const char *path,std::vector<uint8_t>& bytes){std::ifstream file(path,std::ios::binary);bytes.assign(std::istreambuf_iterator<char>(file),std::istreambuf_iterator<char>());return bool(file)&&!bytes.empty();}
int main(int argc,char **argv){if(argc==1)return runAudioFmTests();if(argc!=4||std::string(argv[1])!="--original")return 2;using namespace Snatcher;std::vector<uint8_t> main,fm;std::string error;if(!readFile(argv[2],main)||!readFile(argv[3],fm))return 2;std::vector<FmInstrument> instruments;if(!parseFmInstruments(fm.data(),fm.size(),instruments,error)){std::fprintf(stderr,"%s\n",error.c_str());return 1;}std::printf("INSTRUMENTS\t%zu\n",instruments.size());for(unsigned i=0;i<instruments.size();++i){const FmInstrument& inst=instruments[i];std::printf("I\t%u\t%u\t%u",i,unsigned(inst.algorithm),unsigned(inst.feedback));for(const FmOperator& op:inst.operators)std::printf("\t%u\t%u\t%u\t%u\t%u\t%u\t%u\t%u\t%u\t%u",unsigned(op.detune),unsigned(op.multiple),unsigned(op.totalLevel),unsigned(op.rateScale),unsigned(op.attackRate),unsigned(op.amplitudeModulation),unsigned(op.decayRate),unsigned(op.sustainRate),unsigned(op.sustainLevel),unsigned(op.releaseRate));std::printf("\n");}size_t commands=0,channels=0,events=0,unsupported=0,ended=0;
 for(unsigned command=1;command<241;++command){FmCommandAsset asset;if(!readFmCommandAsset(main.data(),main.size(),fm.data(),fm.size(),uint16_t(command),asset,error))continue;++commands;std::printf("A\t%u\t%u\t%u\t%zu\t%zu\n",command,unsigned(asset.music),asset.sequenceIndex,asset.sourceOffset,asset.bytes.size());for(size_t channelIndex=0;channelIndex<asset.channels.size();++channelIndex){uint32_t offset=asset.channels[channelIndex];std::printf("C\t%u\t%u\n",command,unsigned(offset));++channels;FmSequenceReader reader;if(!reader.start(asset.bytes,offset,error,asset.firstChannel+channelIndex==6||asset.firstChannel+channelIndex==7))return 1;for(unsigned horizon=0;horizon<512;++horizon){FmSequenceEvent event;if(!reader.next(event,error)){++unsupported;std::printf("U\t%u\t%zu\t%u\t%s\n",command,reader.cursor(),reader.cursor()<asset.bytes.size()?unsigned(asset.bytes[reader.cursor()]):256u,error.c_str());break;}++events;if(reader.ended()){++ended;break;}}}}
 std::printf("CORPUS\t%zu\t%zu\t%zu\t%zu\t%zu\n",commands,channels,events,unsupported,ended);return commands?0:1;
}
#endif
